SAMPLE_STUDENT = {
    "full_name": "Aditi Sharma",
    "email": "student@quizcraft.com",
    "password": "Student@123",
    "phone": "9876543210",
}

SAMPLE_FACULTY = {
    "full_name": "Dr. Rohan Mehta",
    "email": "faculty@quizcraft.com",
    "password": "Faculty@123",
    "phone": "9876500000",
}


class Command(BaseCommand):
    help = "Seed MongoDB with sample users, 14 subjects and 350 questions."

    def handle(self, *args, **options):
        ensure_indexes()
        self.stdout.write("Connecting to MongoDB and seeding data...")

        faculty = self._get_or_create_user(SAMPLE_FACULTY, role="faculty")
        self._get_or_create_user(SAMPLE_STUDENT, role="student")

        for name, description in SUBJECTS:
            if not collections.subjects.find_one({"name": name}):
                SubjectService.create_subject(name, description)
                self.stdout.write(self.style.SUCCESS(f"  + Subject created: {name}"))
            else:
                self.stdout.write(f"  = Subject already exists: {name}")

        created_count = 0
        skipped_count = 0

        for subject, text, options, correct, difficulty, marks, explanation in QUESTIONS:
            exists = collections.questions.find_one({
                "subject": subject,
                "question_text": text,
            })
            if exists:
                skipped_count += 1
                continue

            question = QuestionService.create(
                subject=subject,
                question_text=text,
                options=options,
                correct_answer=correct,
                difficulty=difficulty,
                marks=marks,
                created_by=str(faculty["_id"]),
            )

            # The current QuestionService.create() signature in this project
            # does not expose explanation, so keep the existing API unchanged
            # and add the explanation directly to the MongoDB document.
            question_id = question.get("_id") if isinstance(question, dict) else None
            if question_id is not None:
                collections.questions.update_one(
                    {"_id": question_id},
                    {"$set": {"explanation": explanation}},
                )
            else:
                collections.questions.update_one(
                    {"subject": subject, "question_text": text},
                    {"$set": {"explanation": explanation}},
                )
            created_count += 1

        total_q = collections.questions.count_documents({})
        total_s = collections.subjects.count_documents({})

        self.stdout.write(self.style.SUCCESS(
            f"\nSeed complete. {total_s} subjects, {total_q} questions in the bank."
        ))
        self.stdout.write(
            f"Added this run: {created_count} | Skipped existing: {skipped_count}"
        )
        self.stdout.write("\nSeed question distribution:")
        self.stdout.write("  14 subjects x 10 Easy   = 140 Easy")
        self.stdout.write("  14 subjects x 10 Medium = 140 Medium")
        self.stdout.write("  14 subjects x 5 Hard     = 70 Hard")
        self.stdout.write("  Total = 350 questions")

        self.stdout.write("\nSample credentials:")
        self.stdout.write(
            f"  Student -> email: {SAMPLE_STUDENT['email']}  password: {SAMPLE_STUDENT['password']}"
        )
        self.stdout.write(
            f"  Faculty -> email: {SAMPLE_FACULTY['email']}  password: {SAMPLE_FACULTY['password']}"
        )

    def _get_or_create_user(self, sample, role):
        existing = collections.users.find_one({"email": sample["email"]})
        if existing:
            self.stdout.write(
                f"  = {role.capitalize()} account already exists: {sample['email']}"
            )
            return existing

        try:
            user = AuthService.register(
                full_name=sample["full_name"],
                email=sample["email"],
                password=sample["password"],
                confirm_password=sample["password"],
                role=role,
                phone=sample.get("phone", ""),
            )
        except ValidationError:
            user = collections.users.find_one({"email": sample["email"]})

        self.stdout.write(self.style.SUCCESS(
            f"  + {role.capitalize()} account created: {sample['email']}"
        ))
        return user